<?php
namespace Tests\Feature;
use App\Models\{Category,Inventory,Product,ProductMedia,Role,StockCountTask,User,Warehouse,WarehouseInventory};
use App\Services\AdminNavigation;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;
class WarehouseStockCountTest extends TestCase {
 use RefreshDatabase;
 private function product(string $name='Counted cake'):Product{$category=Category::firstOrCreate(['slug'=>'counting'],['name'=>'Counting']);$p=Product::create(['category_id'=>$category->id,'slug'=>str($name)->slug().uniqid(),'premium_marketing_name'=>$name,'product_code'=>'PC-'.uniqid(),'is_active'=>true]);$p->inventory()->create(['quantity_on_hand'=>10,'low_stock_threshold'=>2]);return $p;}
 private function manager():User{$role=Role::create(['name'=>'Inventory Manager','permissions'=>AdminNavigation::normalize(['access.admin.warehouses.index','warehouses.manage','access.admin.stock-counts.index','stock-counts.manage','access.admin.inventory.index','inventory.manage'])]);return User::factory()->create(['role_id'=>$role->id,'is_active'=>true]);}
 private function worker():User{$role=Role::where('name',Role::WAREHOUSE_USER)->firstOrFail();return User::factory()->create(['role_id'=>$role->id,'is_active'=>true]);}
 public function test_existing_inventory_is_available_in_main_warehouse_and_adjustments_keep_total_in_sync():void{$p=$this->product();$main=Warehouse::where('is_default',true)->firstOrFail();$this->assertSame('10.000',WarehouseInventory::whereBelongsTo($p)->whereBelongsTo($main)->value('quantity_on_hand'));$this->actingAs($this->manager())->post(route('admin.inventory.adjust',$p),['warehouse_id'=>$main->id,'action'=>'set','quantity'=>14,'expected_quantity'=>10,'low_stock_threshold'=>3,'reason'=>'Count correction'])->assertRedirect();$this->assertSame('14.000',$p->fresh()->inventory->quantity_on_hand);$this->assertDatabaseHas('inventory_movements',['product_id'=>$p->id,'warehouse_id'=>$main->id,'quantity_change'=>4]);}
 public function test_admin_assigns_worker_accumulates_adjustments_and_submission_freezes_variance():void{$manager=$this->manager();$worker=$this->worker();$p=$this->product();$main=Warehouse::where('is_default',true)->firstOrFail();$this->actingAs($manager)->post(route('admin.stock-counts.store'),['scope'=>'specific','warehouse_id'=>$main->id,'assigned_to'=>$worker->id,'product_ids'=>[$p->id],'starts_at'=>now()->format('Y-m-d\TH:i'),'due_at'=>now()->addDay()->format('Y-m-d\TH:i'),'instructions'=>'Count carefully'])->assertRedirect();$task=StockCountTask::firstOrFail();$this->assertSame('CNT-0001',$task->number);$this->actingAs($worker)->get(route('admin.stock-counts.mine'))->assertOk()->assertSee('CNT-0001');$item=$task->items()->firstOrFail();$this->postJson(route('admin.stock-counts.items.save',[$task,$item]),['quantity_change'=>8,'note'=>'Opening shelf'])->assertOk()->assertJsonPath('quantity',8)->assertJsonPath('counted',1);$this->postJson(route('admin.stock-counts.items.save',[$task,$item]),['quantity_change'=>4,'note'=>'Second tray'])->assertOk()->assertJsonPath('quantity',12);$this->postJson(route('admin.stock-counts.items.save',[$task,$item]),['quantity_change'=>-2,'note'=>'Two damaged'])->assertOk()->assertJsonPath('quantity',10);$this->assertDatabaseCount('stock_count_item_logs',3);$this->get(route('admin.stock-counts.show',[$task,'q'=>'Counted cake']))->assertOk()->assertSee('sc-count-table')->assertSee('data-count-total>10',false)->assertDontSee('System inventory');$this->actingAs($manager)->get(route('admin.stock-counts.show',$task))->assertOk()->assertSee('System inventory')->assertSee('Two damaged')->assertSee('Logs');$this->getJson(route('admin.stock-counts.items.logs',[$task,$item]))->assertOk()->assertJsonPath('total',10)->assertJsonCount(3,'logs')->assertJsonPath('logs.0.change',-2);$this->actingAs($worker)->post(route('admin.stock-counts.submit',$task))->assertRedirect();$item->refresh();$this->assertSame('submitted',$task->fresh()->status);$this->assertSame('10.000',$item->system_quantity_snapshot);$this->assertSame(0.0,$item->variance);$p->inventory()->update(['quantity_on_hand'=>7]);$this->assertSame('10.000',$item->fresh()->system_quantity_snapshot);}
 public function test_worker_cannot_see_another_workers_task_or_admin_pages():void{$manager=$this->manager();$worker=$this->worker();$other=$this->worker();$p=$this->product();$task=StockCountTask::create(['number'=>'CNT-0099','warehouse_id'=>Warehouse::where('is_default',true)->value('id'),'assigned_to'=>$other->id,'created_by'=>$manager->id,'scope'=>'specific']);$task->items()->create(['product_id'=>$p->id]);$this->actingAs($worker)->get(route('admin.stock-counts.show',$task))->assertForbidden();$this->get(route('admin.warehouses.index'))->assertForbidden();$this->get(route('admin.stock-counts.create'))->assertForbidden();}
 public function test_manager_can_delete_a_count_task_but_worker_cannot():void{$manager=$this->manager();$worker=$this->worker();$p=$this->product();$task=StockCountTask::create(['number'=>'CNT-0100','warehouse_id'=>Warehouse::where('is_default',true)->value('id'),'assigned_to'=>$worker->id,'created_by'=>$manager->id,'scope'=>'specific']);$item=$task->items()->create(['product_id'=>$p->id,'actual_quantity'=>3]);$this->actingAs($worker)->delete(route('admin.stock-counts.destroy',$task))->assertForbidden();$this->assertDatabaseHas('stock_count_tasks',['id'=>$task->id]);$this->actingAs($manager)->delete(route('admin.stock-counts.destroy',$task))->assertRedirect(route('admin.stock-counts.index'));$this->assertDatabaseMissing('stock_count_tasks',['id'=>$task->id]);$this->assertDatabaseMissing('stock_count_items',['id'=>$item->id]);}
 public function test_count_adjustments_require_safe_values_and_logs_respect_task_access():void{$manager=$this->manager();$worker=$this->worker();$other=$this->worker();$p=$this->product();$task=StockCountTask::create(['number'=>'CNT-0101','warehouse_id'=>Warehouse::where('is_default',true)->value('id'),'assigned_to'=>$worker->id,'created_by'=>$manager->id,'scope'=>'specific']);$item=$task->items()->create(['product_id'=>$p->id]);$this->actingAs($worker)->postJson(route('admin.stock-counts.items.save',[$task,$item]),['quantity_change'=>0])->assertUnprocessable()->assertJsonValidationErrors('quantity_change');$this->postJson(route('admin.stock-counts.items.save',[$task,$item]),['quantity_change'=>2])->assertOk()->assertJsonPath('quantity',2);$this->postJson(route('admin.stock-counts.items.save',[$task,$item]),['quantity_change'=>-1])->assertUnprocessable()->assertJsonValidationErrors('note');$this->postJson(route('admin.stock-counts.items.save',[$task,$item]),['quantity_change'=>-3,'note'=>'Damaged'])->assertUnprocessable()->assertJsonValidationErrors('quantity_change');$this->assertDatabaseCount('stock_count_item_logs',1);$this->actingAs($other)->getJson(route('admin.stock-counts.items.logs',[$task,$item]))->assertForbidden();$this->actingAs($manager)->getJson(route('admin.stock-counts.items.logs',[$task,$item]))->assertOk()->assertJsonPath('total',2)->assertJsonCount(1,'logs');}
 public function test_create_screen_lazy_loads_compact_product_images():void{$manager=$this->manager();$product=$this->product('Fast product picker');$media=ProductMedia::create(['product_id'=>$product->id,'path'=>'products/fast-picker.jpg','original_name'=>'fast-picker.jpg','mime_type'=>'image/jpeg','kind'=>'image','sort_order'=>0]);$url=route('catalogue.media',[$product,$media]);$this->actingAs($manager)->get(route('admin.stock-counts.create'))->assertOk()->assertSee('Fast product picker')->assertSee('sc-product-symbol')->assertSee('class="mmc-lazy-image"',false)->assertSee('src="data:image/gif;base64',false)->assertSee('data-src="'.$url.'"',false);}
 public function test_warehouse_navigation_is_grouped_under_administration():void{$node=collect(AdminNavigation::nodes())->firstWhere('route','admin.warehouses.index');$this->assertSame('Administration',$node['group']);}
 public function test_automatic_order_style_changes_use_default_warehouse_without_corrupting_other_locations():void{$p=$this->product();$main=Warehouse::where('is_default',true)->firstOrFail();$other=Warehouse::create(['name'=>'Freezer Two','storage_type'=>'freezer']);WarehouseInventory::create(['warehouse_id'=>$other->id,'product_id'=>$p->id,'quantity_on_hand'=>10]);Inventory::withoutEvents(fn()=>$p->inventory()->update(['quantity_on_hand'=>20]));$p->inventory->refresh()->update(['quantity_on_hand'=>18]);$this->assertSame('8.000',WarehouseInventory::where('warehouse_id',$main->id)->where('product_id',$p->id)->value('quantity_on_hand'));$this->assertSame('10.000',WarehouseInventory::where('warehouse_id',$other->id)->where('product_id',$p->id)->value('quantity_on_hand'));}
}
